[entities]
// The portal back to Lyra's Chapel in Vesperholm, at the ledge's south edge, facing the ledge; the
// shrines: on the ledge, in the Outer Ward past the gate, and in Herran's study.
A = exit map=vesperholm at=21,3,90 label=Step_through_the_portal model=argent_portal yaw=-90 on=l
B = save_statue
// Light: a cold light on the ledge and in the barbican's rooms, high in the Great Hall and up the keep
// stair; braziers before the barbican and in the ward; candelabra in the halls.
N = light y=4 color=0.9,0.8,0.7 radius=9
Ñ = light y=3 color=0.9,0.75,0.6 radius=7 on=γ
Ò = light y=3 color=0.9,0.75,0.6 radius=7 on=θ
F = brazier
K = candelabra
// Statues along the causeway and in the ward; the Great Hall's pillars.
T = gate_statue
P = pillar
// Herran's household, and the barbican's sealed gate with the two Wardens bound to it, one on the
// deck of each tower, up its lift.
G = grafted_footman
D = door seal=gate model=sealed on=g
L = lift top=8 model=cage on=q
W = castellan_warden seal=gate
// The Hall of Sentinels: its great door from the Great Hall's stair, its rear door onto the keep
// stair, and its two stone giants, each with a piece of its armour to drop.
O = door boss=sentinels_dead on=v
Q = door boss=sentinels_dead rear on=v
U = bulwark_sentinel item=sentinel_plate
V = blade_sentinel item=sentinel_gauntlets
// The library's bookcases, the false wall behind them and the hidden stair down into the mountain.
Ë = bookcase
X = secret_wall on=x
E = exit map=herran_laboratory at=16,2,90 label=Descend_into_the_dark model=sunken_stair yaw=-90 on=x
// Herran's study: his dissecting table; his door, and Herran in his theatre under its broken dome.
Í = dissecting_table
Z = door boss=herran_dead on=z
H = herran
Y = anatomy_dome radius=11 height=1.2
// Finds: Hearth Ash in the ward, Mender's Kits in the chapel, a draught and tonics on the towers'
// decks and in the library.
É = chest item=hearth_ash count=2 gold=90 model=coffer
Ê = chest item=menders_kit count=2 gold=140 model=banded
Ç = chest item=ember_draught count=2 gold=120 model=banded
È = chest item=red_tonic count=3 gold=120 model=worn
Ì = chest item=red_tonic count=3 gold=300 model=banded
// Two pages of Herran's journal.
I = hint text="The sentinels keep the stair, and the stair keeps me.|Below, in the rock, I keep what I have made."
J = hint text="Mother has a hundred hands to hold us. I have eight.|It will be enough. It must be enough."
// The skyline: the Hollow Peak beyond the keep, and the castle's towers.
M = hollow_peak height=140 width=120 yaw=-90 on=%
À = castle_tower style=keep height=40 width=8 on=%
Á = castle_tower style=round height=30 on=%
Â = castle_tower style=octagon height=28 on=%
Ã = castle_tower style=belfry height=32 on=%
Ä = castle_tower style=square height=30 on=#
Å = castle_tower style=round height=26 on=#
Æ = castle_tower style=square height=27 on=#
Î = castle_tower style=octagon height=24 on=#
